      if(block.type==="tier"){inferredTier=undefined;if(tier!==undefined&&Number(block.tier)===tier)result.push(...block.body.flatMap((child:any,childIndex:number)=>calculatorNestedRuleBlock(child,`${path}.body.${childIndex}`,true)));continue;}
