        if(match){inferredTier=Number(match[1]);if(tier===inferredTier){const value=text.slice(match[0].length);if(value)result.push({type:"paragraph",text:value,path});}}
        else{inferredTier=undefined;if(tier===undefined)result.push({type:"paragraph",text,path});}
